"""Long chains of ACCEPTED transactions: exercises commit-side pin/group bookkeeping."""
import json, random, sys
sys.path.insert(0, '/workspace/dev')
import harness, ref

def build(seed, ntx=1500, D=40, G=4, pinned=0.5):
    rng = random.Random(seed)
    # leaf-spine with 2 leaves => both templates share domain 0, footprint {0,1}
    sess = {'topology': ['leaf-spine', 2, 1], 'caps': [10**9]*3,
            'groups': [[rng.randint(1, 8), 10**12] for _ in range(G)],
            'tasks': [[rng.randrange(2), rng.randrange(G), rng.randint(1, 100), 7,
                        1 if rng.random() < pinned else 0] for _ in range(D)],
            'query': {'groups': list(range(G)), 'nodes': [0, 1, 2], 'tasks': list(range(min(D, 8)))},
            'transactions': []}
    r = ref.Ref(sess)
    accepted = 0
    for i in range(ntx):
        for attempt in range(6):
            edits = []
            for _ in range(rng.randint(1, 5)):
                kind = rng.choice(['move', 'weight', 'bind', 'pin', 'quota', 'budget', 'cap', 'class'])
                if kind == 'move': edits.append(['move', rng.randrange(D), rng.randrange(G)])
                elif kind == 'weight': edits.append(['weight', rng.randrange(D), rng.randint(1, 100)])
                elif kind == 'bind': edits.append(['bind', rng.randrange(D), rng.randrange(2)])
                elif kind == 'pin': edits.append(['pin', rng.randrange(D), rng.randint(0, 1)])
                elif kind == 'quota': edits.append(['quota', rng.randrange(G), rng.randint(1, 8)])
                elif kind == 'budget': edits.append(['budget', rng.randrange(G), 10**12])
                elif kind == 'cap': edits.append(['cap', rng.randrange(3), 10**9])
                else: edits.append(['class', rng.randrange(D), 7])
            tx = {'revision': r.revision, 'edits': edits,
                  'query': {'groups': [rng.randrange(G) for _ in range(rng.randint(0, 3))],
                            'nodes': [rng.randrange(3) for _ in range(rng.randint(0, 3))],
                            'tasks': [rng.randrange(D) for _ in range(rng.randint(0, 3))]}}
            snap = (json.dumps(r.tasks), json.dumps(r.quota), json.dumps(r.budget), json.dumps(r.caps), r.revision)
            out = r.transact(tx)
            if out['accepted']:
                accepted += 1
                break
            # restore reference state and retry with a different edit set
            r.tasks, r.quota, r.budget, r.caps, r.revision = json.loads(snap[0]), json.loads(snap[1]), json.loads(snap[2]), json.loads(snap[3]), snap[4]
        sess['transactions'].append(tx)
    return {'version': 2, 'sessions': [sess]}, accepted

fails = 0
for seed in range(int(sys.argv[1]), int(sys.argv[2])):
    req, accepted = build(seed)
    got, p = harness.run_request(req)
    want = ref.run(req)
    if got != want:
        fails += 1
        txs_g = got['sessions'][0]['transactions']; txs_w = want['sessions'][0]['transactions']
        for j, (a, b) in enumerate(zip(txs_g, txs_w)):
            if a != b:
                print('FAIL seed', seed, 'tx', j, json.dumps(req['sessions'][0]['transactions'][j])[:300])
                print(' got ', json.dumps(a)[:400]); print(' want', json.dumps(b)[:400]); break
        break
    print('ok seed %d accepted=%d/%d rev=%d' % (seed, accepted, len(req['sessions'][0]['transactions']),
                                                 got['sessions'][0]['transactions'][-1]['revision']))
print('chain failures:', fails)
PYEOF
cd /workspace/dev && time python3 chain.py 0 6 2>&1|tail -8
